insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-284', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Most collisions in a gas-phase sample do not yield product because', '["they lack either the required energy or the required orientation (or both)","molecules never touch one another","the collision frequency is exactly zero","Faraday''s first law forbids gas reactions"]'::jsonb, 0, 'The exponential energy factor $e^{-E_a/RT}$ is usually ≪ 1, and the steric factor is also less than 1, so only a tiny fraction of hits succeed.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'collision-qual') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
