insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-285', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'The steric factor $P$ introduced in collision theory is less than one when', '["only some geometries of an otherwise energetic collision can lead to reaction","every collision is chemically productive","$E_a$ is exactly zero","the reaction is zero order"]'::jsonb, 0, '$P$ (also called the probability factor) corrects the simple hard-sphere collision rate for orientation and other restrictions.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'collision-qual') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
